surl --cert server.pem --key server.key --user :tok-abc123 --mail-domain example.com --mailbox ann@example.com:annpass --mailbox bob@example.com:bobpass imaps://127.0.0.1:8080/ imap://127.0.0.1:8081/ smtp://127.0.0.1:8082/ &
